import React, { useState } from 'react';
import { 
  Trash2, Plus, Users, MapPin, Play, Clock, 
  Layers, AlertTriangle, CheckCircle 
} from 'lucide-react';

const distributeSubjects = (subjectList, daysCount) => {
  const sorted = [...subjectList].sort((a, b) => a.code.localeCompare(b.code));
  const result = Array.from({ length: daysCount }, () => []);
  sorted.forEach((subject, index) => {
    result[index % daysCount].push(subject);
  });
  return result;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // Local UI-only states
  const [examDays, setExamDays] = useState(1);
  const [examDates, setExamDates] = useState(['']);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(1);
  const [pName, setPName] = useState("");
  const [roomNum, setRoomNum] = useState("");

  const handleExamDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 1);
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  // UPDATED HANDLERS: These now call onUpdate()
  const handleAddProctor = () => {
    if (!pName) return;
    const updated = [...proctors, { id: Date.now(), name: pName.toUpperCase() }];
    onUpdate('proctors', updated);
    setPName("");
  };

  const handleAddRoom = (type) => {
    if (!roomNum) return;
    const updated = [...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type }];
    onUpdate('rooms', updated);
    setRoomNum("");
  };

  const handleAddSubject = () => {
    const code = document.getElementById(`sC-${deptId}`).value;
    const name = document.getElementById(`sN-${deptId}`).value;
    if(code && name) {
      const updated = { ...subjects, [selectedYear]: [...subjects[selectedYear], { code: code.toUpperCase(), name }] };
      onUpdate('subjects', updated);
      document.getElementById(`sC-${deptId}`).value = '';
      document.getElementById(`sN-${deptId}`).value = '';
    }
  };

  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert("Add subjects first!");
    if (rooms.length === 0) return alert("Add rooms first!");
    if (examDates.some(d => !d)) return alert("Set dates first!");

    const dailySplit = distributeSubjects(yearSubjects, examDays);
    const finalGeneratedData = [];

    for (let dayIdx = 0; dayIdx < dailySplit.length; dayIdx++) {
      const daySubjects = dailySplit[dayIdx];
      const currentDate = examDates[dayIdx];
      const blockDuration = daySubjects.length; 

      const [sh, sm] = startTime.split(':').map(Number);
      const endTime = `${String(sh + blockDuration).padStart(2, '0')}:${String(sm).padStart(2, '0')}`;

      const vacantRooms = rooms.filter(r => !globalSchedule.some(as => 
        as.room === r.number && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)
      ));

      if (vacantRooms.length < sectionCount) return alert(`Not enough rooms on Day ${dayIdx+1}`);

      const chosenRooms = vacantRooms.slice(0, sectionCount).map(r => r.number);

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;
        daySubjects.forEach(sub => {
          finalGeneratedData.push({
            subject_code: sub.code, subject_name: sub.name, section: sectionID,
            year_level: selectedYear, dept_code: deptCode, exam_date: currentDate,
            start_time: startTime, end_time: endTime, room: chosenRooms[s],
            proctor: proctors[0]?.name || "STAFF"
          });
        });
      }
    }
    onGenerate(finalGeneratedData, examDates);
  };

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden">
      {/* HEADER */}
      <div className="bg-slate-900 p-8 text-white flex justify-between items-center border-b-4 border-blue-600">
        <div className="flex items-center gap-3">
          <Layers className="text-blue-500" />
          <h2 className="text-3xl font-black uppercase tracking-tighter">{deptName} ({deptCode})</h2>
        </div>
        <div className="flex gap-4">
          <div className="text-center bg-slate-800 px-4 py-2 rounded-xl">
            <p className="text-[8px] text-slate-500 uppercase font-black">Rooms</p>
            <p className="text-xl font-black">{rooms.length}</p>
          </div>
        </div>
      </div>

      {/* TABS */}
      <div className="flex bg-slate-50 p-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === t ? 'bg-white shadow-md text-blue-600' : 'text-slate-400'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-8">
        {activeTab === 'subjects' && (
          <div className="space-y-4">
            <div className="grid grid-cols-4 gap-2 bg-slate-50 p-4 rounded-2xl">
              <select className="p-2 rounded-lg text-xs font-bold" onChange={(e) => setSelectedYear(e.target.value)}>
                {[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}
              </select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-2 rounded-lg text-xs font-bold" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-2 rounded-lg text-xs font-bold" />
              <button onClick={handleAddSubject} className="bg-blue-600 text-white rounded-lg"><Plus /></button>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {subjects[selectedYear].map((s, i) => (
                <div key={i} className="flex justify-between p-3 bg-white border rounded-xl items-center">
                  <span className="text-xs font-bold">{s.code}</span>
                  <button onClick={() => {
                    const updated = { ...subjects, [selectedYear]: subjects[selectedYear].filter((_,idx)=>idx!==i) };
                    onUpdate('subjects', updated);
                  }}><Trash2 size={14} className="text-slate-300 hover:text-red-500" /></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'proctors' && (
          <div className="space-y-4">
            <div className="flex gap-2">
              <input value={pName} onChange={e=>setPName(e.target.value)} placeholder="NAME" className="flex-1 p-3 border rounded-xl text-xs font-bold" />
              <button onClick={handleAddProctor} className="bg-emerald-600 text-white px-6 rounded-xl font-bold text-xs uppercase">Add</button>
            </div>
            {proctors.map(p => (
              <div key={p.id} className="flex justify-between p-4 bg-slate-50 rounded-xl">
                <span className="font-black text-xs">{p.name}</span>
                <button onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))}><Trash2 size={14}/></button>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'rooms' && (
          <div className="space-y-4">
            <div className="flex gap-2">
              <input value={roomNum} onChange={e=>setRoomNum(e.target.value)} placeholder="ROOM #" className="flex-1 p-3 border rounded-xl text-xs font-bold" />
              <button onClick={() => handleAddRoom('Dept')} className="bg-amber-600 text-white px-4 rounded-xl text-[10px] font-black uppercase">Dept</button>
            </div>
            <div className="grid grid-cols-4 gap-2">
              {rooms.map(r => (
                <div key={r.id} className="p-4 bg-slate-50 rounded-xl text-center relative group">
                  <span className="font-black text-lg">{r.number}</span>
                  <button className="absolute top-1 right-1 opacity-0 group-hover:opacity-100" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={12}/></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-3xl p-6 text-white space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[8px] font-black text-slate-500 uppercase block mb-1">Exam Days</label>
                <input type="number" value={examDays} onChange={e=>handleExamDayChange(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl text-blue-400 font-black" />
              </div>
              <div>
                <label className="text-[8px] font-black text-slate-500 uppercase block mb-1">Start Time</label>
                <input type="time" value={startTime} onChange={e=>setStartTime(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl text-blue-400 font-black" />
              </div>
            </div>
            <div className="space-y-2">
              {examDates.map((d, i) => (
                <input key={i} type="date" value={d} onChange={e => {
                  const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated);
                }} className="w-full bg-slate-800 p-2 rounded-lg text-xs font-bold" />
              ))}
            </div>
            <button onClick={handleGenerateClick} className="w-full bg-blue-600 py-4 rounded-2xl font-black uppercase tracking-widest flex items-center justify-center gap-2">
              <Play size={18} fill="currentColor" /> Run Engine
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
